CREATE TRIGGER RefCusTariffBRCharacteristic_Combined
	ON RefCusTariffBRCharacteristic
	FOR INSERT, UPDATE, DELETE
	AS
	IF (SELECT CASE WHEN EXISTS(SELECT 1 FROM INSERTED) AND NOT EXISTS(SELECT 1 FROM DELETED) THEN 1 ELSE 0 end) = 1
	BEGIN
		UPDATE t SET
		ZB1_DataSetPK = COALESCE(inserted.ZB1_ZZ1_Tariff, inserted.ZB1_ZZ5_Nomenclature),
		ZB1_DataSetCode = CASE WHEN inserted.ZB1_ZZ1_Tariff IS NOT NULL THEN 'ZZ1' ELSE CASE WHEN inserted.ZB1_ZZ5_Nomenclature IS NOT NULL THEN 'ZZ5' END END 
		FROM RefCusTariffBRCharacteristic t
		JOIN inserted ON t.ZB1_PK = inserted.ZB1_PK
	END

	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT t.ZB1_DataSetPK, t.ZB1_DataSetCode
	FROM RefCusTariffBRCharacteristic t
	JOIN inserted ON t.ZB1_PK = inserted.ZB1_PK
	UNION
	SELECT ZB1_DataSetPK, ZB1_DataSetCode
	FROM deleted

	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN @sourcePK ON RVC_ParentPK = PK AND RVC_ParentCode = TablePrefix
	WHERE RVC_IsPublished = 1

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO

